import { RecordRepository } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function expectRange(fn: () => unknown, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const repository = new RecordRepository();
deepEqual(repository.all(), [], 'new repository is empty');
equal(repository.find('missing'), null, 'unknown ID is not found');
equal(repository.remove('missing'), false, 'removing unknown ID returns false');
expectRange(() => repository.save({ id: '', label: 'x' }), 'empty ID is rejected');
expectRange(() => repository.save({ id: '   ', label: 'x' }), 'whitespace-only ID is rejected');

const first = { id: ' a ', label: 'First' };
repository.save(first);
repository.save({ id: 'b', label: 'Second' });
first.id = 'changed';
first.label = 'mutated';
deepEqual(repository.all(), [{ id: ' a ', label: 'First' }, { id: 'b', label: 'Second' }], 'save copies input and preserves exact valid ID');

repository.save({ id: ' a ', label: 'Replacement' });
deepEqual(repository.all(), [{ id: ' a ', label: 'Replacement' }, { id: 'b', label: 'Second' }], 'replacement retains first-insertion order');

const found = repository.find(' a ') as { id: string; label: string };
deepEqual(found, { id: ' a ', label: 'Replacement' }, 'find returns stored value');
found.label = 'caller edit';
deepEqual(repository.find(' a '), { id: ' a ', label: 'Replacement' }, 'find returns a fresh record');

const all = repository.all();
assert(all !== repository.all(), 'all returns a new array');
assert(all[0] !== repository.all()[0], 'all returns new record objects');
all[0].label = 'changed outside';
all.push({ id: 'extra', label: 'extra' });
deepEqual(repository.all(), [{ id: ' a ', label: 'Replacement' }, { id: 'b', label: 'Second' }], 'mutating all result does not affect storage');

equal(repository.remove(' a '), true, 'remove reports an existing record');
deepEqual(repository.all(), [{ id: 'b', label: 'Second' }], 'remove deletes only requested record');

